function wrap(text,max){const lines=[];String(text).split('\n').forEach(p=>{let line='';p.split(/\s+/).filter(Boolean).forEach(word=>{if(line&&line.length+word.length+1>max){lines.push(line);line=word}else line+=(line?' ':'')+word});lines.push(line)});return lines}
function svgText(text,x,y,size,max,color,font,opts={}){const lines=wrap(text,max);return `<text x="${x}" y="${y}" fill="${color}" font-family="${font}" font-size="${size}" font-weight="${opts.bold?'700':'400'}" text-anchor="${opts.anchor||'middle'}" ${opts.tracking?`letter-spacing="${opts.tracking}"`:''}>${lines.map((l,i)=>`<tspan x="${x}" dy="${i?size*1.12:0}">${esc(l)}</tspan>`).join('')}</text>`}
function templateSvg(look=state.look,thumb=false){return PosterDesign.svg(state,look)}
function syncInputs(){['kicker','headline','subtitle','price','currency','footer','paper','font'].forEach(k=>$('#'+k).value=state[k]);$('#bgColor').value=state.customBg||palettes[state.palette][0];$('#inkColor').value=state.customInk||palettes[state.palette][1];$('#brief').value=state.brief}
function renderEditor(){ canvasEditor.render();$('#looks').innerHTML=PosterDesign.titles.map((n,i)=>`<button class="look ${state.look===i?'active':''}" data-look="${i}" aria-label="Choose ${n}">${canvasEditor.showModels?PosterDesign.model(i):posterSvg(i,true)}<small>${n}</small></button>`).join('');$('#palettes').innerHTML=palettes.map((p,i)=>`<button class="palette ${state.palette===i?'active':''}" data-palette="${i}" style="--a:${p[0]};--b:${p[1]}" aria-label="Color palette ${i+1}"></button>`).join('');$('#sizeCaption').textContent=paperSize(state).label+' · '+paperSize(state).w+' × '+paperSize(state).h+' mm';renderArt();save()}
function renderArt(){canvasEditor.renderLibrary()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category)setCategory(b.dataset.category);if(b.dataset.direction!==undefined)initializeDesign(Number(b.dataset.direction));if(b.dataset.example){$('#brief').value=b.dataset.example;$('#brief').focus()}if(b.dataset.look!==undefined){state.look=Number(b.dataset.look);renderEditor()}if(b.dataset.palette!==undefined){state.palette=Number(b.dataset.palette);delete state.customBg;delete state.customInk;syncInputs();renderEditor()}if(b.dataset.art){state.art=b.dataset.art;state.photo=null;renderEditor()}if(b.dataset.step){const n=Number(b.dataset.step);if(n===1)showStep(1);else if(n===2)setCategory(state.category);else if(state.headline||state.blank){syncInputs();renderEditor();showStep(3)}else toast('Choose a direction to start your design.')}if(b.dataset.tab){$$('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));$('#detailsTab').hidden=b.dataset.tab!=='details';$('#artworkTab').hidden=b.dataset.tab!=='artwork'}});
$('#briefForm').addEventListener('submit',e=>{e.preventDefault();state.brief=PromptEngine.clean($('#brief').value);$('#brief').value=state.brief;if(!state.brief){toast('Tell us a little about your poster, or choose a starting point.');return}const ranked=rankBrief(state.brief);if(!ranked[0].score){toast('No clear match yet. Choose a starting point below.');save();return}setCategory(ranked[0].c.id,true)});
$('#backIdea').onclick=()=>showStep(1);$('#backDirections').onclick=()=>setCategory(state.category);$('#startOver').onclick=()=>{showStep(1);$('#brief').focus()};$('#drafts').onclick=()=>{if(!state.headline){toast('Your draft will appear here when you create a poster.');return}syncInputs();renderEditor();showStep(3);toast('Your latest draft is ready.')};
['kicker','headline','subtitle','price','currency','footer','paper','font'].forEach(k=>$('#'+k).addEventListener('input',()=>{state[k]=$('#'+k).value;renderEditor()}));['bgColor','inkColor'].forEach((id,i)=>$('#'+id).addEventListener('input',()=>{state[i?'customInk':'customBg']=$('#'+id).value;renderEditor()}));$('#artSearch').addEventListener('input',renderArt);$('#removePhoto').onclick=()=>{state.photo=null;$('#upload').value='';renderEditor();toast('Photo removed.')};
$('#upload').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPEG, or WebP photo.');return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');const ratio=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);state.photo=canvas.toDataURL('image/jpeg',.85);bitmap.close();renderEditor();toast('Photo added. Choose a look to see it in your poster.')}catch{toast('This photo could not be opened. Try another image.')}});
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
$('#download').onclick=async()=>{const svg=posterSvg();const filename=(state.headline||'paperplane-poster').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50);if($('#exportType').value==='svg'){downloadBlob(new Blob([svg],{type:'image/svg+xml'}),filename+'.svg');toast('Your vector poster is ready.');return}const b=$('#download');b.disabled=true;b.textContent='Exporting…';const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=state.paper==='a3'?3508:state.paper==='square'?2362:2480;canvas.height=state.paper==='a3'?4961:state.paper==='square'?2362:3508;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Export failed');downloadBlob(blob,filename+'.png');toast('Your high-resolution PNG is ready.')}catch{toast('PNG export could not finish. Try downloading the SVG instead.')}finally{URL.revokeObjectURL(url);b.disabled=false;b.textContent='Download ↗'}};
if(state.headline&&state.designVersion!==2){
  try{localStorage.setItem('paperplane-previous-draft',JSON.stringify(state))}catch{}
  state.scenes={};state.designVersion=2;state.usePalette=false;
}
const canvasEditor=new EasyStudio();
document.querySelector('#homePreviews').innerHTML=['food','music','community'].map((c,i)=>`<div class="home-poster home-poster-${i}">${PosterDesign.preview(c,i===2?2:0)}</div>`).join('');
function posterSvg(look=state.look,thumb=false){return canvasEditor.svg(look,thumb)}
syncInputs();renderArt();if(state.step===2)setCategory(state.category);else if(state.step===3&&(state.headline||state.blank)){renderEditor();showStep(3)}else showStep(1);
